static int note_cands(const char *pin, const char **out, int maxn)
{
  int n = 0;
  int i;
  size_t plen;

  if (!pin || !pin[0])
    {
      return 0;
    }
  plen = strlen(pin);
  for (i = 0; i < (int)(sizeof(s_py) / sizeof(s_py[0])) && n < maxn; i++)
    {
      if (strcmp(s_py[i].py, pin) == 0 ||
          strncmp(s_py[i].py, pin, plen) == 0)
        {
          int d = 0;
          int j;
          for (j = 0; j < n; j++)
            {
              if (strcmp(out[j], s_py[i].word) == 0)
                {
                  d = 1;
                  break;
                }
            }
          if (!d)
            {
              out[n++] = s_py[i].word;
            }
        }
    }
  return n;
}

static void note_paint_cands(void)
{
  const char *c[NOTE_CAND_MAX];
  int n;
  int i;

  if (!s_kb_cand)
    {
      return;
    }
  lv_obj_clean(s_kb_cand);
  if (s_kb_mode != 0 || s_pin_len == 0)
    {
      return;
    }
  n = note_cands(s_pin, c, NOTE_CAND_MAX);
  for (i = 0; i < n; i++)
    {
      lv_obj_t *b = dm_btn(s_kb_cand, c[i], c[i], 40, 24, 0x0d3a4a,
                           C_ACCENT, note_kb_confirm_cb, (void *)c[i]);
      lv_obj_set_pos(b, i * 42, 0);
    }
}

static void note_kb_confirm_cb(lv_event_t *e)
{
  const char *w = (const char *)lv_event_get_user_data(e);

  if (w && w[0])
    {
      snprintf(s_draft, NOTE_LEN_MAX, "%s", w);
      s_draft_len = (int)strlen(s_draft);
      s_pin_len = 0;
      s_pin[0] = 0;
    }
  note_paint();
  dm_show(PAGE_NOTE_ADD);
}

static void note_kb_key_cb(lv_event_t *e)
{
  const char *k = (const char *)lv_event_get_user_data(e);

  if (!k || !k[0])
    {
      return;
    }
  if (strcmp(k, "DEL") == 0)
    {
      if (s_kb_mode == 0 && s_pin_len > 0)
        {
          s_pin[--s_pin_len] = 0;
        }
      else if (s_draft_len > 0)
        {
          s_draft_len--;
          while (s_draft_len > 0 &&
                 ((unsigned char)s_draft[s_draft_len] & 0xc0) == 0x80)
            {
              s_draft_len--;
            }
          s_draft[s_draft_len] = 0;
        }
    }
  else if (strcmp(k, "SP") == 0)
    {
      if (s_kb_mode == 0 && s_pin_len > 0)
        {
          const char *c[NOTE_CAND_MAX];
          int n = note_cands(s_pin, c, NOTE_CAND_MAX);
          if (n > 0)
            {
              size_t cur = strlen(s_draft);
              size_t add = strlen(c[0]);
              if (cur + add < sizeof(s_draft) - 1)
                {
                  memcpy(s_draft + cur, c[0], add + 1);
                  s_draft_len = (int)(cur + add);
                }
              s_pin_len = 0;
              s_pin[0] = 0;
            }
        }
    }
  else if (strcmp(k, "OK") == 0)
    {
      note_kb_confirm_cb(e);
      return;
    }
  else
    {
      size_t n = strlen(k);
      if (s_kb_mode == 0)
        {
          if (s_pin_len + (int)n < (int)sizeof(s_pin) - 1)
            {
              memcpy(s_pin + s_pin_len, k, n + 1);
              s_pin_len += (int)n;
            }
        }
      else if (s_draft_len + (int)n < NOTE_LEN_MAX - 1)
        {
          memcpy(s_draft + s_draft_len, k, n + 1);
          s_draft_len += (int)n;
        }
    }
  note_paint();
  note_paint_cands();
}

static void note_kb_mode_cb(lv_event_t *e)
{
  int m = (int)(intptr_t)lv_event_get_user_data(e);
  int i;

  s_kb_mode = m;
