static int note_cands(const char *pin, const char **out, int maxn)
{
  int n = 0;
  int i;
  size_t plen;

  if (!pin || !pin[0])
    {
      return 0;
    }
  plen = strlen(pin);
  for (i = 0; i < (int)(sizeof(s_py) / sizeof(s_py[0])) && n < maxn; i++)
    {
      if (strcmp(s_py[i].py, pin) == 0 ||
          strncmp(s_py[i].py, pin, plen) == 0)
        {
          int d = 0;
          int j;
          for (j = 0; j < n; j++)
            {
              if (strcmp(out[j], s_py[i].word) == 0)
                {
                  d = 1;
                  break;
                }
            }
          if (!d)
            {
              out[n++] = s_py[i].word;
            }
        }
    }
  return n;
}

