{
  const char *w = (const char *)lv_event_get_user_data(e);

  if (w && w[0])
    {
      /* Append one CJK character (3 bytes UTF-8) to draft */
      size_t cur = s_draft_len;
      if (cur + 3 < NOTE_LEN_MAX - 1)
        {
          memcpy(s_draft + cur, w, 3);
          s_draft_len = (int)(cur + 3);
